# Col 0: Description, Col 1: Fixed-maturity, Col 2: Callable issues, Col 3: Cumulative

current_callable_year = None
nat_defense_by_year = {}

for row in parser.rows:
    if len(row) >= 4:
        desc = row[0]
        fixed = row[1] if len(row) > 1 else ""
        callable_amt = row[2] if len(row) > 2 else ""

        # Check if it's a year header (just a year, no description)
        if desc.isdigit() and desc.isnumeric():
            current_callable_year = desc
            continue

        # Skip totals and empty rows
        if 'Total' in desc or not desc:
            continue

        # Check for National Defense Series
        if 'Nat. Defense Series' in desc or 'National Defense Series' in desc:
            print(f"Year {current_callable_year}: {desc}")
            print(f"  Fixed: {fixed}, Callable: {callable_amt}")

            if current_callable_year not in nat_defense_by_year:
                nat_defense_by_year[current_callable_year] = []

            nat_defense_by_year[current_callable_year].append({
                'desc': desc,
                'fixed': fixed,
                'callable': callable_amt
            })

print("\n=== Summary by year first callable ===")
for year, entries in nat_defense_by_year.items():
    print(f"\nYear {year}:")
    total = 0
    for e in entries:
        # If there's a callable amount, use that; otherwise use fixed
        amt = e['callable'] if e['callable'] else e['fixed']
        # Clean up the amount - remove commas
        amt_clean = amt.replace(',', '').replace('%', '')
        if amt_clean.isdigit():
            print(f"  {e['desc']}: {amt} (using {'callable' if e['callable'] else 'fixed'})")
            total += int(amt_clean)
    print(f"  Total: {total}")
